// The host rehearsal provider (#693, tools/ring_vs_ssd/rehearsal): the frame content must equal the golden one the fake pzrec produces (tools/ring_vs_ssd/rehearsal/testdata/frames.json,
// regenerated by test_rehearsal.py --write), and the ring must behave like the PL's: ids from the clock, one epoch per ARM, frozen by STOP, a window of the newest N frames.
#include "backend/processing/pz/RehearsalProvider.h"

#include "support/assert.h"

#include <nlohmann/json.hpp>

#include <chrono>
#include <filesystem>
#include <fstream>
#include <thread>

namespace fs = std::filesystem;
namespace pz = backend::pz;
using backend::processing::pz::RehearsalProvider;

namespace {

std::string fnv(const std::vector<uint8_t>& b) {
    uint64_t h = 0xCBF29CE484222325ull;
    for (uint8_t c : b) h = (h ^ c) * 0x100000001B3ull;
    char buf[32];
    std::snprintf(buf, sizeof buf, "%016llx", static_cast<unsigned long long>(h));
    return buf;
}

} // namespace

int main(int argc, char** argv) {
    MIB_REQUIRE(argc >= 2, "usage: rehearsal_provider_test <tools/ring_vs_ssd/rehearsal/testdata/frames.json>");
    std::ifstream in(argv[1]);
    MIB_REQUIRE(static_cast<bool>(in), std::string("cannot open ") + argv[1]);
    const auto golden = nlohmann::json::parse(in);
    const double fps = golden.at("fps").get<double>();

    for (const auto& [idText, want] : golden.at("frames").items()) {
        pz::RingFrame f;
        RehearsalProvider::fillFrame(1, std::stoull(idText), fps, f);
        const std::string ctx = "frame " + idText + ": ";
        MIB_EXPECT(fnv(f.gray) == want.at("gray_fnv"), ctx + "gray equals the fake's");
        MIB_EXPECT(fnv(f.mask) == want.at("mask_fnv"), ctx + "mask equals the fake's");
        MIB_EXPECT(f.timestampTicks == want.at("ticks").get<uint64_t>(), ctx + "ticks");
        const auto& cells = want.at("cells");
        MIB_REQUIRE(f.cells.size() == cells.size(), ctx + "cell count");
        for (size_t i = 0; i < cells.size(); ++i) {
            const auto& c = f.cells[i];
            std::vector<uint32_t> words(c.payload.begin(), c.payload.end());
            words.push_back(c.x | static_cast<uint32_t>(c.y) << 16);
            words.push_back(c.width | static_cast<uint32_t>(c.height) << 16);
            words.push_back((static_cast<uint32_t>(f.cells.size()) & 0xFF) << 24 | (static_cast<uint32_t>(c.index) & 0xFF) << 16 | (c.valid ? 1u : 0u));
            words.push_back(c.payloadValidity);
            MIB_EXPECT(words == cells[i].get<std::vector<uint32_t>>(), ctx + "cell " + std::to_string(i) + " words equal the fake's");
        }
    }

    // The ring's behaviour. 1 kHz, a ring of 20 frames.
    const fs::path dir = fs::temp_directory_path() / ("rehearsal_provider_" + std::to_string(std::chrono::steady_clock::now().time_since_epoch().count()));
    fs::create_directories(dir);
    {
        RehearsalProvider p(1000.0, 20, dir.string());
        MIB_EXPECT(!p.ringStatus().valid, "not armed: no ring");
        pz::RingFrame f;
        std::string why;
        MIB_EXPECT(p.ringRead(0, f, &why) == pz::RingRead::Unavailable, "not armed: no read");
        MIB_REQUIRE(p.ringFramesWanted() == 20 && p.ringTickHz() == 100000000u, "wants its ring, device ticks");
        std::string err;
        MIB_REQUIRE(p.start(1, &err), err);
        MIB_EXPECT(fs::exists(dir / "emu.json"), "the state file for the fake pzrec");
        std::this_thread::sleep_for(std::chrono::milliseconds(60));
        auto st = p.ringStatus();
        MIB_EXPECT(st.valid && !st.frozen && st.epoch == 3 && st.count() > 0 && st.count() <= 20, "running: armed, one epoch, the newest frames");
        p.stop();
        st = p.ringStatus();
        MIB_REQUIRE(st.valid && st.frozen && st.state == 0, "stopped: frozen");
        MIB_EXPECT(st.final > 40 && st.count() == 20 && st.lo == st.final - 20 && st.head == static_cast<int64_t>(st.final) - 1, "a full ring of the newest 20, sequence = frame id - 1");
        std::this_thread::sleep_for(std::chrono::milliseconds(30));
        MIB_EXPECT(p.ringStatus().final == st.final, "a stopped ring does not move");
        MIB_EXPECT(p.ringRead(st.lo - 1, f, &why) == pz::RingRead::OutOfRange, "below the window");
        MIB_EXPECT(p.ringRead(st.final, f, &why) == pz::RingRead::OutOfRange, "above the window");
        MIB_REQUIRE(p.ringRead(st.final - 1, f, &why) == pz::RingRead::Ok, why);
        MIB_EXPECT(f.seq == st.final - 1 && f.frameId == st.final, "the newest frame");
        pz::RingFrame again;
        RehearsalProvider::fillFrame(st.epoch, st.final, 1000.0, again);
        MIB_EXPECT(again.gray == f.gray && again.mask == f.mask && again.timestampTicks == f.timestampTicks, "a read is the pure function of the id");
        MIB_REQUIRE(p.start(2, &err), err);
        MIB_EXPECT(p.ringStatus().epoch == 4, "a re-ARM is a new epoch");
        p.stop();
        auto j = nlohmann::json::parse(std::ifstream(dir / "emu.json"));
        MIB_EXPECT(j["epoch"] == 4 && j["running"] == false && j["stop_ns"].get<int64_t>() > 0 && j["fps"] == 1000.0, "the state file follows the provider");
    }
    fs::remove_all(dir);
    return mib::test::exitCode();
}
